create table if not exists templates(id bigint generated by default as identity primary key,slug text unique not null,name text not null,price numeric(12,2) not null check(price>0),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists orders(id text primary key,name text not null,contact_number text not null,email text not null,delivery_email text not null,template_slug text not null,platform text not null check(platform in ('excel','powerbi','googlesheets','powerautomate','tableau')),requirements text not null,amount numeric(12,2) not null,status text not null,utr text,payment_screenshot_url text,revision_count integer not null default 0 check(revision_count between 0 and 2),admin_action text,admin_action_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists consents(id bigint generated by default as identity primary key,order_id text references orders(id) on delete cascade,terms_version text not null,required_consent boolean not null,offers_consent boolean not null default false,revision_consent boolean not null,ip text,created_at timestamptz not null default now());
create table if not exists revisions(id bigint generated by default as identity primary key,order_id text references orders(id) on delete cascade,message text not null,revision_number integer not null check(revision_number between 1 and 2),created_at timestamptz not null default now());
create table if not exists deliverables(id bigint generated by default as identity primary key,order_id text references orders(id) on delete cascade,file_url text,created_at timestamptz not null default now());
create table if not exists email_logs(id bigint generated by default as identity primary key,order_id text,recipient text,template text,status text,error text,created_at timestamptz not null default now());
create unique index if not exists revisions_order_number on revisions(order_id,revision_number);
